"""Layered configuration resolver.

Precedence, lowest to highest:
  1. defaults.toml
  2. --system file
  3. --user file
  4. environment variables prefixed APP_ (APP_DB__HOST -> db.host)
  5. repeated --set key=value overrides

resolve() returns (merged, provenance) where provenance maps each dotted
leaf path to the name of the layer that supplied it.
"""

from __future__ import annotations

import argparse
import json
import sys
import tomllib
from pathlib import Path
from typing import Any

ENV_PREFIX = "APP_"
NEST_SEP = "__"
KEY_SEP = "."

DEFAULTS_PATH = Path(__file__).with_name("defaults.toml")

LAYER_DEFAULTS = "defaults"
LAYER_SYSTEM = "system"
LAYER_USER = "user"
LAYER_ENV = "env"
LAYER_CLI = "cli"


def _load_toml(path: str | Path | None) -> dict[str, Any]:
    if path is None:
        return {}
    with open(path, "rb") as f:
        return tomllib.load(f)


def _coerce(raw: str) -> Any:
    """Best-effort scalar coercion for env/CLI string values."""
    text = raw.strip()
    try:
        return tomllib.loads(f"v = {text}")["v"]
    except tomllib.TOMLDecodeError:
        return raw


def _set_leaf(
    target: dict[str, Any], dotted: str, value: Any
) -> None:
    parts = dotted.split(KEY_SEP)
    node = target
    for part in parts[:-1]:
        child = node.get(part)
        if not isinstance(child, dict):
            child = {}
            node[part] = child
        node = child
    node[parts[-1]] = value


def _leaves(tree: dict[str, Any], prefix: str = "") -> list[tuple[str, Any]]:
    out: list[tuple[str, Any]] = []
    for key, val in tree.items():
        path = f"{prefix}{key}"
        if isinstance(val, dict):
            out.extend(_leaves(val, prefix=f"{path}."))
        else:
            out.append((path, val))
    return out


def _env_layer(environ: dict[str, str] | None) -> dict[str, Any]:
    """APP_ prefixed vars -> nested dict; APP_DB__HOST -> db.host."""
    tree: dict[str, Any] = {}
    if environ is None:
        return tree
    for name, raw in environ.items():
        if not name.startswith(ENV_PREFIX):
            continue
        dotted = name[len(ENV_PREFIX):].lower().replace(NEST_SEP, KEY_SEP)
        if not dotted:
            continue
        _set_leaf(tree, dotted, _coerce(raw))
    return tree


def _set_layer(pairs: list[str] | None) -> dict[str, Any]:
    tree: dict[str, Any] = {}
    if not pairs:
        return tree
    for pair in pairs:
        if "=" not in pair:
            raise ValueError(f"--set expects key=value, got: {pair!r}")
        key, _, raw = pair.partition("=")
        _set_leaf(tree, key.strip(), _coerce(raw))
    return tree


def resolve(
    defaults: dict[str, Any] | None = None,
    system: dict[str, Any] | None = None,
    user: dict[str, Any] | None = None,
    environ: dict[str, str] | None = None,
    sets: list[str] | None = None,
    defaults_path: str | Path | None = None,
    system_path: str | Path | None = None,
    user_path: str | Path | None = None,
) -> tuple[dict[str, Any], dict[str, str]]:
    """Merge all layers; return (merged dict, {leaf dotted path: layer name})."""
    layers = [
        (LAYER_DEFAULTS, defaults if defaults is not None else _load_toml(defaults_path or DEFAULTS_PATH)),
        (LAYER_SYSTEM, system if system is not None else _load_toml(system_path)),
        (LAYER_USER, user if user is not None else _load_toml(user_path)),
        (LAYER_ENV, _env_layer(environ if environ is not None else dict(__import__("os").environ))),
        (LAYER_CLI, _set_layer(sets)),
    ]

    merged: dict[str, Any] = {}
    provenance: dict[str, str] = {}
    for layer_name, tree in layers:
        for path, value in _leaves(tree):
            _set_leaf(merged, path, value)
            provenance[path] = layer_name
    return merged, provenance


def explain(key: str, merged: dict[str, Any], provenance: dict[str, str]) -> str:
    path = key.lower().replace(NEST_SEP, KEY_SEP)
    if path not in provenance:
        raise KeyError(f"unknown config key: {key!r}")
    return f"{path} = {merged[path]!r} (source: {provenance[path]})"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Layered configuration resolver")
    parser.add_argument("--defaults", help="path to defaults TOML file")
    parser.add_argument("--system", help="path to system TOML file")
    parser.add_argument("--user", help="path to user TOML file")
    parser.add_argument(
        "--set", action="append", default=[], metavar="KEY=VALUE",
        help="override a leaf (repeatable, highest precedence)",
    )
    parser.add_argument(
        "--explain", metavar="KEY",
        help="print one key's value and its source layer instead of full JSON",
    )
    args = parser.parse_args(argv)

    merged, provenance = resolve(
        defaults_path=args.defaults,
        system_path=args.system,
        user_path=args.user,
        sets=args.set,
    )
    if args.explain:
        try:
            print(explain(args.explain, merged, provenance))
        except KeyError as exc:
            parser.error(str(exc.args[0]))
    else:
        print(json.dumps(merged, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())

